/**
 *
 * Splitter is utilized to separate and resize panels.
 *
 * [Live Demo](https://www.primereact.org/splitter/)
 *
 * @module SplitterRoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseSplitterCollapseEvent, UseSplitterExposes, UseSplitterProps, UseSplitterResizeEvent, UseSplitterState } from '@primereact/types/headless/splitter';
/**
 * Event fired when the Splitter resize starts.
 */
export interface SplitterRootResizeStartEvent extends UseSplitterResizeEvent {
}
/**
 * Event fired during Splitter resize.
 */
export interface SplitterRootResizeEvent extends UseSplitterResizeEvent {
}
/**
 * Event fired when the Splitter resize ends.
 */
export interface SplitterRootResizeEndEvent extends UseSplitterResizeEvent {
}
/**
 * Event fired when a Splitter panel collapses or expands.
 */
export interface SplitterRootCollapseEvent extends UseSplitterCollapseEvent {
}
/**
 * Defines passthrough(pt) options type in Splitter component.
 */
export type SplitterRootPassThroughType<E> = PassThroughType<SplitterRootInstance, E>;
/**
 * Defines passthrough(pt) options of Splitter component.
 */
export interface SplitterRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: SplitterRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the panel's DOM element.
     */
    panel?: SplitterRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the gutter's DOM element.
     */
    gutter?: SplitterRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the handle's DOM element.
     */
    handle?: SplitterRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in Splitter component.
 */
export interface SplitterRootProps extends BaseComponentProps<SplitterRootInstance, Omit<UseSplitterProps, 'onResize' | 'onResizeStart' | 'onResizeEnd' | 'onCollapse'>, SplitterRootPassThrough> {
    /**
     *  Callback invoked when resize starts.
     * @param {SplitterRootResizeStartEvent} event - Custom resize start event.
     */
    onResizeStart?: ((event: SplitterRootResizeStartEvent) => void) | undefined;
    /**
     * Callback invoked during resize with current panel sizes.
     * @param {SplitterRootResizeEvent} event - Custom resize event.
     */
    onResize?: ((event: SplitterRootResizeEvent) => void) | undefined;
    /**
     * Callback invoked when resize ends.
     * @param {SplitterRootResizeEndEvent} event - Custom resize end event.
     */
    onResizeEnd?: ((event: SplitterRootResizeEndEvent) => void) | undefined;
    /**
     * Callback invoked when a panel collapses or expands.
     * @param {SplitterRootCollapseEvent} event - Custom collapse event.
     */
    onCollapse?: ((event: SplitterRootCollapseEvent) => void) | undefined;
}
/**
 * Defines valid state in Splitter component.
 * @extends UseSplitterState
 */
export interface SplitterRootState extends UseSplitterState {
}
/**
 * Defines the methods and properties exposed by Splitter component.
 * @extends UseSplitterExposes
 */
export interface SplitterRootExposes extends UseSplitterExposes {
}
/**
 * Instance of Splitter component.
 */
export type SplitterRootInstance = ComponentInstance<SplitterRootProps, SplitterRootState, SplitterRootExposes>;
